import { readFileSync, writeFileSync } from "node:fs";

const source = new URL("../packages/core/runtimes/pricing.json", import.meta.url);
const target = new URL("../server/internal/pricing/bundled_generated.go", import.meta.url);
const catalog = JSON.parse(readFileSync(source, "utf8"));
const json = JSON.stringify({ version: catalog.version, rows: catalog.rows, aliases: catalog.aliases ?? {} });
// A quoted Go string also safely embeds catalog names containing backticks.
const output = `// Code generated by scripts/generate-pricing-bundle.mjs; DO NOT EDIT.\npackage pricing\n\nconst bundledJSON = ${JSON.stringify(json)}\n`;
if (process.argv.includes("--check")) {
  if (readFileSync(target, "utf8").replaceAll("\r\n", "\n") !== output) {
    throw new Error("Pricing bundle is stale. Run node scripts/generate-pricing-bundle.mjs");
  }
} else {
  writeFileSync(target, output);
}
